def getIntersectionNode(headA, headB):
    seen = set()
    cur = headA
    while cur:
        seen.add(cur)
        cur = cur.next
    cur = headB
    while cur:
        if cur in seen:
            return cur
        cur = cur.next
    return None

def multiply(num1: str, num2: str) -> str:
    if num1 == "0" or num2 == "0":
        return "0"
    m, n = len(num1), len(num2)
    res = [0] * (m + n)
    for i in range(m - 1, -1, -1):
        a = int(num1[i])
        for j in range(n - 1, -1, -1):
            res[i + j + 1] += a * int(num2[j])
    for k in range(len(res) - 1, 0, -1):
        res[k - 1] += res[k] // 10
        res[k] %= 10
    start = 0
    while start < len(res) - 1 and res[start] == 0:
        start += 1
    return ''.join(map(str, res[start:]))
